import numpy as np


def engine(grid, action, data):
    g = np.asarray(grid).copy()
    H, W = g.shape

    # Current contiguous zero-progress on the top row (right-to-left)
    # and bottom row (left-to-right).
    kt = 0
    while kt < W and g[0, W - 1 - kt] == 0:
        kt += 1
    kb = 0
    while kb < W and g[H - 1, kb] == 0:
        kb += 1
    k = min(kt, kb)

    hit_object = False

    # Directional actions move the 5x5 color-10 blocks by one 5-cell step.
    if action in (1, 2, 3, 4):
        blocks = []
        for r in range(4, H - 4, 5):
            for c in range(4, W - 4, 5):
                if np.all(g[r:r + 5, c:c + 5] == 10):
                    blocks.append((r, c, r + 4, c + 4))

        valid_indices = []
        new_boxes = {}

        for i, (r0, c0, r1, c1) in enumerate(blocks):
            cx = (c0 + c1) // 2
            dx = 0
            dy = 0

            if action == 1:
                dy = -5
            elif action == 2:
                dy = 5
            elif action == 3:
                # Mirrored horizontal "left": away from vertical center.
                if cx < W / 2.0:
                    dx = -5
                elif cx > W / 2.0:
                    dx = 5
            elif action == 4:
                # Mirrored horizontal "right": toward vertical center.
                if cx < W / 2.0:
                    dx = 5
                elif cx > W / 2.0:
                    dx = -5

            if dx == 0 and dy == 0:
                continue

            nr0 = r0 + dy
            nc0 = c0 + dx
            nr1 = r1 + dy
            nc1 = c1 + dx

            if nr0 < 0 or nc0 < 0 or nr1 >= H or nc1 >= W:
                continue

            # Destination must be clear floor color 5 in the current grid.
            if not np.all(g[nr0:nr1 + 1, nc0:nc1 + 1] == 5):
                continue

            valid_indices.append(i)
            new_boxes[i] = (nr0, nc0, nr1, nc1)

        keep = [True] * len(valid_indices)
        for a in range(len(valid_indices)):
            for b in range(a + 1, len(valid_indices)):
                ia = valid_indices[a]
                ib = valid_indices[b]
                ar0, ac0, ar1, ac1 = new_boxes[ia]
                br0, bc0, br1, bc1 = new_boxes[ib]
                if not (ar1 < br0 or br1 < ar0 or ac1 < bc0 or bc1 < ac0):
                    keep[a] = False
                    keep[b] = False

        final_moves = [valid_indices[idx] for idx in range(len(valid_indices)) if keep[idx]]

        if final_moves:
            out = g.copy()
            for i in final_moves:
                r0, c0, r1, c1 = blocks[i]
                out[r0:r1 + 1, c0:c1 + 1] = 5
            for i in final_moves:
                nr0, nc0, nr1, nc1 = new_boxes[i]
                out[nr0:nr1 + 1, nc0:nc1 + 1] = 10
            g = out

    # Click action: clicking a color-10 object registers a hit.
    elif action == 6:
        if isinstance(data, dict):
            try:
                x = int(round(float(data.get("x", -1))))
                y = int(round(float(data.get("y", -1))))
            except Exception:
                x = -1
                y = -1
            if 0 <= y < H and 0 <= x < W and g[y, x] == 10:
                hit_object = True

    # Progress-bar tick rule inferred from the observed transitions.
    tick = False
    if action == 6:
        tick = hit_object
    else:
        if k > 0:
            if action in (1, 3):
                tick = (k % 2) == 1
            elif action in (4, 5):
                tick = (k % 2) == 0
            else:
                tick = False

    if tick:
        if kt < W:
            g[0, W - 1 - kt] = 0
        if kb < W:
            g[H - 1, kb] = 0

    return g


def is_level_complete(grid):
    g = np.asarray(grid)
    H, W = g.shape
    if H == 0 or W == 0:
        return False

    # Completion by fully filling both HUD progress bars with zeros.
    if np.all(g[0] == 0) and np.all(g[-1] == 0):
        return True

    # Also accept a state where all movable color-10 objects are gone.
    if not np.any(g == 10):
        return True

    return False
